/* SPDX-License-Identifier: Apache-2.0 */
/* eslint-env browser */
/* global Chart */
/* eslint-disable no-undef */
import {replayChart} from '../../assets/replay_chart.js';
replayChart({logsUrl: 'assets/logs.json', label: 'Aiga Meta Evolution Metric', color: 'red'});

import { evaluate, validate, canonical } from "./engine.mjs";
import { parseJSON } from "./json.mjs";
import { messages } from "./i18n.mjs";
const $ = (id) => document.getElementById(id);
let lang = "en",
    revision = 0,
    report = null,
    lastInput = null,
    serial = 0;
const t = (k) => messages[lang][k] || k;
const numeric = new Set([
    "effortHours",
    "maxProjects",
    "minSupportingSources",
    "baseline",
    "current",
    "valuePoints",
]);
function element(tag, text) {
    const el = document.createElement(tag);
    if (text !== undefined) el.textContent = text;
    return el;
}
function field(parent, key, value, options) {
    const wrap = element("div"),
        label = element("label");
    label.dataset.t = key;
    label.textContent = t(key);
    const control = element(options ? "select" : "input");
    control.id = "field-" + ++serial;
    control.dataset.key = key;
    label.htmlFor = control.id;
    if (options)
        for (const option of options) {
            const el = element("option", t(option));
            el.value = option;
            el.dataset.t = option;
            control.append(el);
        }
    else {
        control.type = "text";
        if (numeric.has(key)) control.inputMode = "numeric";
    }
    control.value = value;
    wrap.append(label, control);
    parent.append(wrap);
    return control;
}
function row(collection, data) {
    const card = element("fieldset");
    card.className = "business-row";
    card.dataset.collection = collection;
    const legend = element("legend", data.id);
    card.append(legend);
    const fields = element("div");
    fields.className = "pair";
    for (const [key, value] of Object.entries(data))
        field(
            fields,
            key,
            Array.isArray(value) ? value.join(", ") : value,
            key === "direction" ? ["increase", "decrease"] : undefined
        );
    card.append(fields);
    const remove = element("button", t("remove"));
    remove.type = "button";
    remove.dataset.t = "remove";
    remove.className = "quiet";
    remove.addEventListener("click", () => {
        card.remove();
        invalidate();
    });
    card.append(remove);
    card.addEventListener("input", () => {
        legend.textContent = card.querySelector('[data-key="id"]').value;
        remove.setAttribute(
            "aria-label",
            t("remove") + " " + legend.textContent
        );
    });
    remove.setAttribute("aria-label", t("remove") + " " + data.id);
    $(collection).append(card);
}
function fill(s) {
    validate(s);
    $("metadata").replaceChildren();
    $("policy").replaceChildren();
    field($("metadata"), "id", s.id);
    field($("metadata"), "kind", s.provenance.kind, [
        "constructed",
        "supplied",
    ]);
    field($("metadata"), "note", s.provenance.note);
    for (const [k, v] of Object.entries(s.policy)) field($("policy"), k, v);
    for (const collection of ["observations", "opportunities"]) {
        $(collection).replaceChildren();
        s[collection].forEach((r) => row(collection, r));
    }
}
function integer(raw) {
    if (!/^(?:0|[1-9][0-9]*)$/.test(raw))
        throw Error("Whole decimal integer required");
    const n = Number(raw);
    if (!Number.isSafeInteger(n)) throw Error("Integer too large");
    return n;
}
function values(container) {
    const out = {};
    for (const el of container.querySelectorAll("[data-key]")) {
        const key = el.dataset.key;
        out[key] = numeric.has(key)
            ? integer(el.value)
            : key === "evidenceIds"
            ? el.value.split(",").map((s) => s.trim())
            : el.value;
    }
    return out;
}
function bounded(input) {
    validate(input);
    if (new TextEncoder().encode(canonical(input)).length > 128000)
        throw Error("Input exceeds 128000 bytes");
    return input;
}
function read() {
    const m = values($("metadata"));
    return bounded({
        schema: "agialpha.business2.input.v1",
        id: m.id,
        provenance: { kind: m.kind, note: m.note },
        policy: values($("policy")),
        observations: [...$("observations").children].map(values),
        opportunities: [...$("opportunities").children].map(values),
    });
}
function invalidate() {
    revision++;
    report = null;
    lastInput = null;
    $("result").hidden = true;
    $("evidence").disabled = true;
    $("download").disabled = true;
    $("error").hidden = true;
    $("status").textContent = t("changed");
}
function render() {
    if (!report) return;
    const p = report.plan;
    $("summary").textContent =
        (p.selectedIds.join(", ") || t("empty")) +
        " · " +
        p.totalValuePoints +
        " " +
        t("points") +
        " · " +
        p.totalEffortHours +
        " " +
        t("hours") +
        " · " +
        p.remainingEffortHours +
        " " +
        t("remaining");
    $("review").replaceChildren();
    for (const r of report.research.observations) {
        const card = element("article");
        card.className = "report-card";
        card.append(
            element("h3", r.id + " · " + r.metric),
            element(
                "p",
                r.baseline +
                    " → " +
                    r.current +
                    " " +
                    r.unit +
                    " · " +
                    t("delta") +
                    ": " +
                    r.delta
            ),
            element(
                "p",
                t(r.supports ? "supports" : "noSupport") + " · " + r.source
            )
        );
        $("review").append(card);
    }
    $("portfolio").replaceChildren();
    for (const r of report.research.opportunities) {
        const card = element("article");
        card.className = "report-card";
        card.append(
            element("h3", r.title + " · " + t(r.reason)),
            element(
                "p",
                r.valuePoints +
                    " " +
                    t("points") +
                    " · " +
                    r.effortHours +
                    " " +
                    t("hours")
            ),
            element(
                "p",
                t("sources") + ": " + (r.supportingSources.join(" · ") || "0")
            )
        );
        $("portfolio").append(card);
    }
    $("raw").textContent = JSON.stringify(report, null, 2);
    $("digest").textContent =
        "SHA-256 input: " +
        report.inputDigest +
        " · report: " +
        report.reportDigest;
    $("result").hidden = false;
    $("evidence").disabled = false;
    $("download").disabled = false;
}
async function run() {
    invalidate();
    const own = revision;
    $("status").textContent = t("pending");
    try {
        const input = structuredClone(read());
        const result = await evaluate(input);
        if (own !== revision) return;
        lastInput = input;
        report = result;
        render();
        $("status").textContent = t("ready");
    } catch {
        if (own !== revision) return;
        $("error").textContent = t("invalid");
        $("error").hidden = false;
        $("status").textContent = "";
    }
}
function translate() {
    document.documentElement.lang = lang;
    for (const el of document.querySelectorAll("[data-t]"))
        el.textContent = t(el.dataset.t);
    $("language").textContent = lang === "en" ? "FR" : "EN";
    $("language").setAttribute(
        "aria-label",
        lang === "en" ? "Passer en français" : "Switch to English"
    );
    for (const card of document.querySelectorAll(".business-row"))
        card.querySelector("button").setAttribute(
            "aria-label",
            t("remove") + " " + card.querySelector('[data-key="id"]').value
        );
    if (!$("error").hidden) $("error").textContent = t("invalid");
    $("status").textContent = t(report ? "ready" : "changed");
    render();
}
$("language").onclick = () => {
    lang = lang === "en" ? "fr" : "en";
    translate();
};
$("workspace").addEventListener("input", invalidate);
$("workspace").addEventListener("change", invalidate);
$("workspace").onsubmit = (e) => {
    e.preventDefault();
    run();
};
const example = parseJSON(await (await fetch("assets/example.json")).text());
$("reset").onclick = () => {
    invalidate();
    fill(example);
    run();
};
$("addObservation").onclick = () => {
    if ($("observations").children.length >= 64) return;
    row("observations", {
        id: "observation-" + ++serial,
        source: "",
        metric: "",
        unit: "",
        baseline: 0,
        current: 0,
        direction: "increase",
    });
    invalidate();
};
$("addOpportunity").onclick = () => {
    if ($("opportunities").children.length >= 16) return;
    row("opportunities", {
        id: "project-" + ++serial,
        title: "",
        effortHours: 1,
        valuePoints: 0,
        evidenceIds: [],
    });
    invalidate();
};
$("import").onchange = async () => {
    const file = $("import").files[0];
    if (!file) return;
    invalidate();
    const own = revision;
    try {
        if (file.size > 1048576) throw Error("Too large");
        const parsed = parseJSON(
            new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(
                await file.arrayBuffer()
            ),
            true,
            1048576
        );
        let input = parsed;
        if (
            parsed &&
            [
                "agialpha.business2.evidence.v1",
                "agialpha.business2.notebook-evidence.v1",
            ].includes(parsed.schema)
        ) {
            if (Object.keys(parsed).sort().join("|") !== "input|report|schema")
                throw Error("Unknown evidence fields");
            input = parsed.input;
        } else if (file.size > 128000) throw Error("Input exceeds byte limit");
        bounded(input);
        if (own !== revision) return;
        fill(input);
        await run();
    } catch {
        if (own === revision) {
            $("error").hidden = false;
            $("error").textContent = t("invalid");
        }
    } finally {
        if ($("import").files[0] === file) $("import").value = "";
    }
};
function download(value, name) {
    const url = URL.createObjectURL(
        new Blob([JSON.stringify(value)], {
            type: "application/json",
        })
    );
    const a = element("a");
    a.href = url;
    a.download = name;
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
}
$("download").onclick = () => {
    if (lastInput && report) download(lastInput, "observations.json");
};
$("evidence").onclick = () => {
    if (lastInput && report)
        download(
            {
                schema: "agialpha.business2.evidence.v1",
                input: lastInput,
                report,
            },
            "business2-report.json"
        );
};
fill(example);
await run();

/* SPDX-License-Identifier: Apache-2.0 */
:root {
    color-scheme: dark;
    font-family: Inter, ui-sans-serif, system-ui, sans-serif;
    background: #100b20;
    color: #f6f0ff;
    --muted: #c4b7da;
    --accent: #d5b5ff;
    --line: #584268;
}
* {
    box-sizing: border-box;
}
body {
    margin: 0;
    background: radial-gradient(ellipse at 80% 0, #54297d66, transparent 45%);
}
nav,
header,
main,
footer {
    max-width: 1280px;
    margin: auto;
    padding: 24px 40px;
    overflow-wrap: anywhere;
}
a {
    color: var(--accent);
    text-underline-offset: 5px;
}
nav {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    border-bottom: 1px solid var(--line);
}
nav > div {
    display: flex;
    align-items: center;
    gap: 20px;
}
nav > a {
    text-decoration: none;
    letter-spacing: 0.12em;
    font-weight: 700;
}
button,
input {
    font: inherit;
}
button,
a,
input,
summary {
    outline-offset: 5px;
}
button:focus-visible,
a:focus-visible,
input:focus-visible,
summary:focus-visible {
    outline: 3px solid #ffe1a2;
}
button {
    min-height: 44px;
    cursor: pointer;
}
#language {
    background: transparent;
    border: 1px solid var(--line);
    color: var(--accent);
    border-radius: 50%;
    min-width: 44px;
}
header {
    display: grid;
    grid-template-columns: 1.6fr 1fr;
    gap: 60px;
    padding-top: 76px;
    padding-bottom: 62px;
    align-items: center;
}
.eyebrow {
    font-size: 0.75rem;
    font-weight: 750;
    letter-spacing: 0.13em;
    color: var(--accent);
    line-height: 1.7;
}
h1 {
    font: 400 clamp(2.7rem, 6vw, 5.5rem) / 1.06 Georgia, serif;
    letter-spacing: -0.035em;
    margin: 22px 0;
}
h2 {
    font: 400 clamp(1.8rem, 3vw, 2.6rem) / 1.2 Georgia, serif;
    margin: 10px 0 20px;
}
h3 {
    font-size: 1.1rem;
    margin: 8px 0 16px;
}
p {
    line-height: 1.7;
}
.lead {
    font-size: 1.12rem;
    color: var(--muted);
}
.scope {
    border: 1px solid #7c579a;
    border-radius: 18px;
    padding: 28px;
    background: linear-gradient(135deg, #3b205b, #211331);
    box-shadow: 0 20px 65px #09061266;
}
.scope span {
    font-size: 0.72rem;
    letter-spacing: 0.13em;
    color: #ead7ff;
    font-weight: 750;
}
.scope p {
    color: #e0d0ee;
    font-size: 0.92rem;
}
.panel {
    padding: 28px;
    border: 1px solid var(--line);
    background: #1a122b;
    border-radius: 18px;
    margin-bottom: 24px;
    min-width: 0;
}
.toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 20px;
    flex-wrap: wrap;
}
.toolbar h3 {
    margin-bottom: 6px;
}
.hint {
    font-size: 0.88rem;
    color: var(--muted);
}
label {
    display: block;
    font-size: 0.88rem;
    margin: 8px 0;
    line-height: 1.4;
}
input:not([type="file"]) {
    width: 100%;
    min-width: 0;
    min-height: 46px;
    background: #100b20;
    border: 1px solid #85679d;
    border-radius: 8px;
    color: #fff;
    padding: 12px;
}
.limits {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 20px;
    margin-top: 18px;
}
.task {
    display: grid;
    grid-template-columns: 1fr 2fr repeat(4, 1fr) 1.6fr auto;
    gap: 12px;
    border-top: 1px solid var(--line);
    padding: 18px 0;
    align-items: end;
}
.task > div {
    min-width: 0;
}
.task .remove {
    background: transparent;
    border: 1px solid #b293c6;
    border-radius: 8px;
    color: #ffe1e9;
    padding: 10px;
    min-width: 44px;
}
.actions {
    display: flex;
    align-items: center;
    gap: 16px;
    flex-wrap: wrap;
    margin-top: 24px;
}
.primary,
.quiet {
    border-radius: 9px;
    padding: 13px 19px;
    line-height: 1.4;
    font-weight: 650;
}
.primary {
    color: #241036;
    background: #d8b9ff;
    border: 1px solid #ead9ff;
}
.quiet {
    color: #ead8ff;
    background: #2c1a42;
    border: 1px solid #9973b5;
}
.file-label {
    position: relative;
    display: block;
    cursor: pointer;
    min-height: 46px;
}
.file-label input {
    display: block;
    max-width: 100%;
    margin-top: 8px;
    font-size: 0.85rem;
}
#status {
    color: var(--muted);
}
#error {
    background: #442533;
    border: 1px solid #cb8c9b;
    padding: 16px;
    border-radius: 9px;
    color: #ffe7e8;
}
.metrics {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 16px;
    margin: 24px 0;
}
.metrics > div {
    padding: 20px;
    background: #302043;
    border-radius: 12px;
}
.metrics strong {
    font-size: 2rem;
    display: block;
    margin-top: 8px;
}
.metrics span {
    color: var(--muted);
}
#steps {
    padding-left: 25px;
}
#steps li,
#omissions li {
    padding: 10px 0;
    line-height: 1.65;
}
details {
    border-top: 1px solid var(--line);
    padding-top: 20px;
}
summary {
    cursor: pointer;
    min-height: 44px;
}
pre {
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    background: #0e0918;
    padding: 20px;
    border-radius: 8px;
    max-height: 500px;
    overflow: auto;
}
.method {
    max-width: 800px;
    padding: 35px 0 55px;
}
.method p {
    color: var(--muted);
}
footer {
    border-top: 1px solid var(--line);
    font-size: 0.85rem;
    color: var(--muted);
    padding-bottom: 40px;
}
.skip {
    position: fixed;
    left: 12px;
    top: -100px;
    padding: 14px;
    background: #fff;
    color: #251334;
    z-index: 10;
}
.skip:focus {
    top: 12px;
}
[hidden] {
    display: none !important;
}
@media (max-width: 1050px) {
    .task {
        grid-template-columns: repeat(4, minmax(0, 1fr));
    }
    .task > div:nth-child(2) {
        grid-column: span 2;
    }
    .task > div:nth-child(7) {
        grid-column: span 2;
    }
}
@media (max-width: 700px) {
    nav,
    header,
    main,
    footer {
        padding-left: 20px;
        padding-right: 20px;
    }
    nav {
        align-items: flex-start;
    }
    nav > div {
        flex-wrap: wrap;
        justify-content: flex-end;
        gap: 12px;
    }
    header {
        display: block;
        padding-top: 35px;
        padding-bottom: 30px;
    }
    .scope {
        margin-top: 28px;
        padding: 22px;
    }
    .panel {
        padding: 20px;
    }
    .limits,
    .metrics {
        grid-template-columns: 1fr;
    }
    .task {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 10px;
    }
    .task > div:nth-child(2) {
        grid-column: span 1;
    }
    .primary,
    .quiet {
        max-width: 100%;
    }
    h1 {
        font-size: clamp(2.6rem, 10vw, 4rem);
    }
}
@media print {
    body {
        background: white;
        color: black;
    }
    nav,
    form,
    .actions,
    footer button {
        display: none;
    }
    .panel,
    .scope,
    .metrics > div {
        background: white;
        color: black;
        border: 1px solid #777;
    }
    .hint,
    .lead,
    p,
    .eyebrow {
        color: #222 !important;
    }
    header,
    main {
        padding: 20px;
    }
    #result {
        display: block;
    }
    pre {
        max-height: none;
        color: black;
        background: white;
    }
}
header {
    display: block;
    max-width: 1050px;
    text-align: left;
}
header h1 {
    max-width: 900px;
}
.notice {
    padding: 18px;
    border: 1px solid #82629f;
    background: #2c1c41;
    border-radius: 12px;
    color: #dfd0ec;
}
.layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: 26px;
    align-items: start;
}
.pair {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
}
.section-head {
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
}
.section-head h2 {
    margin: 0;
}
.panel h3 {
    margin-top: 28px;
}
fieldset {
    border: 1px solid var(--line);
    border-radius: 9px;
    margin: 24px 0 0;
    padding: 16px;
}
fieldset label {
    display: flex;
    gap: 12px;
    align-items: center;
    min-height: 44px;
}
input[type="checkbox"] {
    width: 22px;
    min-height: 22px;
    accent-color: #d8b9ff;
}
select {
    width: 100%;
    min-height: 46px;
    background: #100b20;
    color: white;
    border: 1px solid #85679d;
    border-radius: 8px;
    font: inherit;
    padding: 10px;
}
.vote {
    border-top: 1px solid var(--line);
    padding: 16px 0;
}
.primary {
    margin-top: 20px;
    width: 100%;
}
.metrics {
    grid-template-columns: 1fr 1fr;
}
.metrics strong {
    font-size: 1.6rem;
}
#checks {
    padding-left: 22px;
}
#checks li {
    padding: 10px 0;
    line-height: 1.5;
}
.empty {
    padding-top: 40px;
    padding-bottom: 40px;
}
details {
    margin-top: 24px;
}
nav span {
    font-size: 0.75rem;
    letter-spacing: 0.12em;
    color: var(--muted);
}
@media (max-width: 850px) {
    .layout {
        grid-template-columns: 1fr;
    }
}
@media (max-width: 400px) {
    .pair,
    .metrics {
        grid-template-columns: 1fr;
    }
}
.panel.method {
    padding: 28px;
}
.panel.method h2 {
    font-size: 2rem;
}
select:focus-visible {
    outline: 3px solid #ffe1a2;
    outline-offset: 5px;
}
input[type="file"] {
    width: 100%;
    max-width: 100%;
    min-width: 0;
    font: inherit;
    font-size: 0.85rem;
}
nav > div {
    min-width: 0;
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    justify-content: flex-end;
    align-items: center;
}
.job {
    border-top: 1px solid var(--line);
    padding: 22px 0;
}
.job-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 16px;
}
.job-grid > div {
    min-width: 0;
}
.job h3 {
    margin: 0 0 12px;
}
.passes {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 30px;
}
#result li {
    padding: 10px 0;
    line-height: 1.6;
}
#attempts li {
    border-bottom: 1px solid var(--line);
}
.recovery-check {
    display: flex;
    gap: 12px;
    align-items: center;
    min-height: 44px;
}
#result:focus {
    outline: none;
}
