        .sort((a, b) => codepointOrder(a.id, b.id))
        .map((r) => ({
            ...r,
            delta: r.current - r.baseline,
            supports:
                r.direction === "increase"
                    ? r.current > r.baseline
                    : r.current < r.baseline,
        }));
